select v.id from public.video_posts v join expected e on v.id=(e.original->>'id')::uuid for update of v;
do $$ begin if not ((select count(*)=10 from public.video_posts v join expected e on to_jsonb(v)=e.staged or to_jsonb(v)=e.final)) then raise exception 'Transfer snapshot changed; restore refused'; end if; end $$;
do $$ begin if not ((select count(*)=20 from expected e cross join lateral jsonb_array_elements(e.objects) x join storage.objects o on o.bucket_id='clips' and o.name=x->>'name' where o.owner_id=e.original->>'owner_id' and (o.metadata->>'size')::bigint=(x->>'bytes')::bigint)) then raise exception 'Original Storage backup missing'; end if; end $$;
update public.video_posts v set owner_id=(e.original->>'owner_id')::uuid,video_path=e.original->>'video_path',thumbnail_path=e.original->>'thumbnail_path',status=e.original->>'status',approved_at=(e.original->>'approved_at')::timestamptz from expected e where v.id=(e.original->>'id')::uuid;
commit;
